      await enterTournament(page, count);
      const opening =
        count === 4
          ? ['Ada', 'Dev', 'Bo', 'Cora']
          : ['Ada', 'Hal', 'Dev', 'Emi', 'Cora', 'Finn', 'Bo', 'Gia'];
